-- The webhook source (cycle 7c): an inbound endpoint per sender. The token is generated by Remedy, shown once and kept only as a
-- SHA-256 hash (the way run_tokens does it); the previous hash stays valid until previous_valid_until after a rotation. Limits are
-- per endpoint. An endpoint holds no incident: the incidents of a deleted endpoint stay (their key starts with its name).
CREATE TABLE webhook_endpoints (
  id                    BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name                  TEXT NOT NULL CHECK (name ~ '^[a-z0-9][a-z0-9-]{0,39}$'),
  token_hash            BYTEA NOT NULL,
  previous_token_hash   BYTEA,
  previous_valid_until  TEXT,
  enabled               INTEGER NOT NULL DEFAULT 1,
  auto_diagnose         INTEGER NOT NULL DEFAULT 0,
  resolve_after_seconds INTEGER NOT NULL DEFAULT 86400 CHECK (resolve_after_seconds = 0 OR resolve_after_seconds >= 300),
  rate_per_minute       INTEGER NOT NULL DEFAULT 60 CHECK (rate_per_minute BETWEEN 1 AND 6000),
  new_per_hour          INTEGER NOT NULL DEFAULT 30 CHECK (new_per_hour BETWEEN 1 AND 1000),
  created_at            TEXT NOT NULL,
  last_used_at          TEXT
);

CREATE UNIQUE INDEX webhook_endpoints_name ON webhook_endpoints (lower(name));

-- The source of an incident may now be a webhook. A CHECK is widened in place; no table is rebuilt.
ALTER TABLE incidents DROP CONSTRAINT incidents_source_check;
ALTER TABLE incidents ADD CONSTRAINT incidents_source_check CHECK (source IN ('github', 'alertmanager', 'argocd', 'webhook'));
